sys_script.script:
(function executeRule(current, previous) {
    var accountId = current.getValue('account');
    if (accountId) {
        var account = new GlideRecord('x_274351_finance_0_accounts');
        if (account.get(accountId)) {
            // Set user from account holder
            current.setValue('user', account.getValue('holder'));

            // Set balance before
            var currentBalance = parseFloat(account.getValue('balance') || 0);
            current.setValue('balance_before', currentBalance);

            // Calculate and set balance after
            var amount = parseFloat(current.getValue('amount') || 0);
            var txnType = current.getValue('type');
            var newBalance = currentBalance;

            if (txnType === 'deposit') {
                newBalance = currentBalance + amount;
            } else if (txnType === 'withdrawal' || txnType === 'ach_transfer') {
                newBalance = currentBalance - amount;
            }
            current.setValue('balance_after', newBalance);
        }
    }

    // Set timestamp to current time
    current.setValue('timestamp', new GlideDateTime());

    // Generate TRX number for deposit and withdrawal types
    var txnType = current.getValue('type');
    if (txnType === 'deposit' || txnType === 'withdrawal') {
        var gdt = new GlideDateTime();
        var timestamp = gdt.getValue().replace(/[-:\s]/g, '');
        current.setValue('number', 'TRX-' + timestamp);
    }
})(current, previous);
